30	/**
31	 * Simple JavaBean domain object representing an owner.
32	 *
33	 * @author Ken Krebs
34	 * @author Juergen Hoeller
35	 * @author Sam Brannen
36	 * @author Michael Isvy
37	 */
38	@Entity
39	@Table(name = "owners")
40	public class Owner extends Person {
41	    /**
42	     * The fixed list of public holidays that a registration date must roll forward past, in addition
43	     * to weekends.
44	     */
45	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
46	        LocalDate.of(2026, 1, 1),
47	        LocalDate.of(2026, 1, 26),
48	        LocalDate.of(2026, 4, 25),
49	        LocalDate.of(2026, 12, 25),
50	        LocalDate.of(2026, 12, 28));
51	
52	    @Column(name = "title")
53	    private String title;
54	
55	    @Column(name = "address")
56	    @NotEmpty
57	    private String address;
58	
59	    @Column(name = "address_line1")
60	    private String addressLine1;
61	
62	    @Column(name = "address_line2")
63	    private String addressLine2;
64	
65	    @Column(name = "city")
66	    @NotEmpty
67	    private String city;
68	
69	    @Column(name = "telephone")
70	    @NotEmpty
71	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ followed by 8 to 15 digits)")
72	    private String telephone;
73	
74	    @Column(name = "email")
75	    private String email;
76	
77	    @Column(name = "postcode")
78	    private String postcode;
79	
80	    @Column(name = "registration_date", columnDefinition = "DATE")
81	    private LocalDate registrationDate;
82	
83	    @Column(name = "birth_date", columnDefinition = "DATE")
84	    private LocalDate birthDate;
85	
86	    @Column(name = "customer_code")
87	    private String customerCode;
88	
89	    @Column(name = "household_id")
90	    private String householdId;
91	
92	    @Column(name = "namesake_count")
93	    private Integer namesakeCount;
94	
95	    @Column(name = "possible_duplicate")
96	    private Boolean possibleDuplicate;
97	
98	    @Column(name = "possible_duplicate_of")
99	    private Integer possibleDuplicateOf;
100	
101	    @Column(name = "membership_level_cap")
102	    private Integer membershipLevelCap;
103	
104	    @Column(name = "deleted")
105	    private boolean deleted;
106	
107	    @Transient
108	    private Integer householdSize;
109	
110	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
111	    private Set<Pet> pets;
112	
113	    public String getTitle() {
114	        return this.title;
115	    }
116	
117	    public void setTitle(String title) {
118	        this.title = title;
119	    }
120	
121	    /**
122	     * Derives the owner's salutation for the read-only {@code salutation} field: the title, a single
123	     * space and the lastName when a title is present (e.g. {@code 'DR Who'}), or just the lastName
124	     * when no title was supplied.
125	     */
126	    @Transient
127	    public String getSalutation() {
128	        if (this.title == null || this.title.isBlank()) {
129	            return getLastName();
130	        }
131	        return this.title + " " + getLastName();
132	    }
133	
134	    public String getAddress() {
135	        return this.address;
136	    }
137	
138	    public void setAddress(String address) {
139	        this.address = address;
140	    }
141	
142	    public String getAddressLine1() {
143	        return this.addressLine1;
144	    }
145	
146	    public void setAddressLine1(String addressLine1) {
147	        this.addressLine1 = addressLine1;
148	    }
149	
150	    public String getAddressLine2() {
151	        return this.addressLine2;
152	    }
153	
154	    public void setAddressLine2(String addressLine2) {
155	        this.addressLine2 = addressLine2;
156	    }
157	
158	    public String getCity() {
159	        return this.city;
160	    }
161	
162	    public void setCity(String city) {
163	        this.city = city;
164	    }
165	
166	    public String getTelephone() {
167	        return this.telephone;
168	    }
169	
170	    public void setTelephone(String telephone) {
171	        this.telephone = telephone;
172	    }
173	
174	    public String getEmail() {
175	        return this.email;
176	    }
177	
178	    public void setEmail(String email) {
179	        this.email = email == null ? null : email.toLowerCase();
180	    }
181	
182	    public String getPostcode() {
183	        return this.postcode;
184	    }
185	
186	    public void setPostcode(String postcode) {
187	        this.postcode = postcode;
188	    }
189	
190	    public LocalDate getRegistrationDate() {
191	        return this.registrationDate;
192	    }
193	
194	    public void setRegistrationDate(LocalDate registrationDate) {
195	        this.registrationDate = registrationDate;
196	    }
197	
198	    public LocalDate getBirthDate() {
199	        return this.birthDate;
200	    }
201	
202	    public void setBirthDate(LocalDate birthDate) {
203	        this.birthDate = birthDate;
204	    }
205	
206	    /**
207	     * Derives the owner's age band from the birth date, measured against the registration date:
208	     * {@code 'MINOR'} when under 18, {@code 'ADULT'} for 18 to 64 inclusive, and {@code 'SENIOR'}
209	     * from 65 on. Returns {@code null} when either the birth date or the registration date is absent,
210	     * so an owner created without a birth date has no age band.
211	     */
212	    @Transient
213	    public String getAgeBand() {
214	        if (this.birthDate == null || this.registrationDate == null) {
215	            return null;
216	        }
217	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
218	        if (age < 18) {
219	            return "MINOR";
220	        }
221	        return age < 65 ? "ADULT" : "SENIOR";
222	    }
223	
224	    public String getCustomerCode() {
225	        return this.customerCode;
226	    }
227	
228	    public void setCustomerCode(String customerCode) {
229	        this.customerCode = customerCode;
230	    }
231	
232	    /**
233	     * This owner's current primary identifier. It is the {@code customerCode} today; when the
234	     * customerCode is later unified into a {@code memberId}, this returns the memberId instead.
235	     * Callers that need "whatever identifies the owner right now" (e.g. the structured audit
236	     * event) should read it here so they follow that migration automatically.
237	     */
238	    public String primaryIdentifier() {
239	        return this.customerCode;
240	    }
241	
242	    public String getHouseholdId() {
243	        return this.householdId;
244	    }
245	
246	    public void setHouseholdId(String householdId) {
247	        this.householdId = householdId;
248	    }
249	
250	    public Integer getNamesakeCount() {
251	        return this.namesakeCount;
252	    }
253	
254	    public void setNamesakeCount(Integer namesakeCount) {
255	        this.namesakeCount = namesakeCount;
256	    }
257	
258	    /**
259	     * The number of owners belonging to this owner's household (owners sharing this owner's
260	     * household id, including this owner). Not persisted: it is a live count populated at read
261	     * time and feeds the {@code membershipPoints} calculation. Null when it has not been resolved.
262	     */
263	    public Integer getHouseholdSize() {
264	        return this.householdSize;
265	    }
266	
267	    public void setHouseholdSize(Integer householdSize) {
268	        this.householdSize = householdSize;
269	    }
270	
271	    /**
272	     * Whether this owner was flagged a possible (soft-match) duplicate at creation: it was not a
273	     * hard duplicate, yet it shared an existing owner's lastName and postcode while carrying a
274	     * different telephone. False when no such match existed.
275	     */
276	    public Boolean getPossibleDuplicate() {
277	        return this.possibleDuplicate;
278	    }
279	
280	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
281	        this.possibleDuplicate = possibleDuplicate;
282	    }
283	
284	    /**
285	     * The id of the existing owner this owner soft-matches (same lastName and postcode, different
286	     * telephone), or {@code null} when it is not a possible duplicate.
287	     */
288	    public Integer getPossibleDuplicateOf() {
289	        return this.possibleDuplicateOf;
290	    }
291	
292	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
293	        this.possibleDuplicateOf = possibleDuplicateOf;
294	    }
295	
296	    /**
297	     * The ceiling applied to this owner's derived {@code membershipLevel}, fixed when the owner was
298	     * created: one above the maximum membershipLevel among the household members that already existed
299	     * at that time. The reported membership level is never allowed to exceed this cap. {@code null}
300	     * when the owner had no existing household member at creation, in which case no cap applies.
301	     */
302	    public Integer getMembershipLevelCap() {
303	        return this.membershipLevelCap;
304	    }
305	
306	    public void setMembershipLevelCap(Integer membershipLevelCap) {
307	        this.membershipLevelCap = membershipLevelCap;
308	    }
309	
310	    /**
311	     * Computes this owner's membership points for the given household size. Points start at 0 and
312	     * accumulate: 2 when an email address is present, 1 when the owner had no namesakes at creation
313	     * (namesakeCount is 0), 2 for a household of 3 or more members, and 3 for tenure of one or more
314	     * elapsed fiscal years (the number of 1-July fiscal-year boundaries between the registration date
315	     * and the current date). The household size is supplied by the caller (it is a live, non-persisted
316	     * count), so a {@code null} size contributes no household points.
317	     */
318	    public int membershipPoints(Integer householdSize) {
319	        int points = 0;
320	        if (this.email != null && !this.email.isBlank()) {
321	            points += 2;
322	        }
323	        if (this.namesakeCount != null && this.namesakeCount == 0) {
324	            points += 1;
325	        }
326	        if (householdSize != null && householdSize >= 3) {
327	            points += 2;
328	        }
329	        if (this.registrationDate != null
330	            && fiscalYear(LocalDate.now()) - fiscalYear(this.registrationDate) >= 1) {
331	            points += 3;
332	        }
333	        return points;
334	    }
335	
336	    /**
337	     * Derives this owner's numeric membership level for the given household size from its membership
338	     * points: 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points. The
339	     * result is then capped at {@link #getMembershipLevelCap()} (the ceiling fixed at creation from
340	     * the household this owner joined): when a cap is present the level can never exceed it. No cap is
341	     * applied when the owner had no existing household member at creation.
342	     */
343	    public int membershipLevel(Integer householdSize) {
344	        int points = membershipPoints(householdSize);
345	        int level;
346	        if (points <= 1) {
347	            level = 1;
348	        }
349	        else if (points <= 3) {
350	            level = 2;
351	        }
352	        else if (points <= 5) {
353	            level = 3;
354	        }
355	        else {
356	            level = 4;
357	        }
358	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
359	            level = this.membershipLevelCap;
360	        }
361	        return level;
362	    }
363	
364	    /**
365	     * Whether this owner has been soft-deleted. A newly created owner is not deleted; a
366	     * {@code DELETE /api/owners/{id}} flags it deleted while retaining the row. Deleted owners are
367	     * ignored by the create endpoint's duplicate and identity checks.
368	     */
369	    public boolean isDeleted() {
370	        return this.deleted;
371	    }
372	
373	    public void setDeleted(boolean deleted) {
374	        this.deleted = deleted;
375	    }
376	
377	    /**
378	     * The owner's derived identity key, used as the single basis for duplicate detection: the
379	     * lower-case hex SHA-256 digest over {@code normalizedTelephone + '|' + lowerEmail + '|' +
380	     * soundex(lastName)}, where the telephone and email components are empty when absent. Two
381	     * owners are duplicates only when their whole identity keys are equal, so any single differing
382	     * component (telephone, email or the surname's soundex) yields distinct keys and is allowed.
383	     * Derived from persisted fields, so it is not itself a persistent column.
384	     */
385	    @Transient
386	    public String getIdentityKey() {
387	        String normalizedTelephone = this.telephone == null ? "" : this.telephone;
388	        String lowerEmail = this.email == null ? "" : this.email.toLowerCase();
389	        String seed = normalizedTelephone + "|" + lowerEmail + "|" + soundex(getLastName());
390	        return HashUtils.sha256Hex(seed);
391	    }
392	
393	    /**
394	     * Computes the American Soundex code for a name: the retained first letter followed by three
395	     * digits derived from the remaining consonants (b,f,p,v-&gt;1; c,g,j,k,q,s,x,z-&gt;2; d,t-&gt;3;
396	     * l-&gt;4; m,n-&gt;5; r-&gt;6), with adjacent equal codes collapsed, h and w ignored (so they do
397	     * not separate equal codes) and vowels acting as separators, right-padded with zeros to length
398	     * four. Returns an empty string when the value is null or holds no letters, so surnames that
399	     * sound alike share a code.
400	     */
401	    public static String soundex(String value) {
402	        if (value == null) {
403	            return "";
404	        }
405	        String letters = value.toUpperCase().replaceAll("[^A-Z]", "");
406	        if (letters.isEmpty()) {
407	            return "";
408	        }
409	        StringBuilder code = new StringBuilder();
410	        code.append(letters.charAt(0));
411	        char previous = soundexDigit(letters.charAt(0));
412	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
413	            char c = letters.charAt(i);
414	            if (c == 'H' || c == 'W') {
415	                continue;
416	            }
417	            char digit = soundexDigit(c);
418	            if (digit != '0' && digit != previous) {
419	                code.append(digit);
420	            }
421	            previous = digit;
422	        }
423	        while (code.length() < 4) {
424	            code.append('0');
425	        }
426	        return code.toString();
427	    }
428	
429	    /** Maps a letter to its Soundex digit, or {@code '0'} for vowels, y, h and w. */
430	    private static char soundexDigit(char c) {
431	        return switch (c) {
432	            case 'B', 'F', 'P', 'V' -> '1';
433	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
434	            case 'D', 'T' -> '3';
435	            case 'L' -> '4';
436	            case 'M', 'N' -> '5';
437	            case 'R' -> '6';
438	            default -> '0';
439	        };
440	    }
441	
442	    /**
443	     * Establishes the effective registration date at persist time, so the create-time default
444	     * applies to any persistence path.
445	     */
446	    @PrePersist
447	    protected void defaultRegistrationDate() {
448	        resolveRegistrationDate();
449	    }
450	
451	    /**
452	     * Resolves this owner's effective registration date and stores it: the supplied value is used, or
453	     * the server's current date when none was supplied, and the result is rolled forward onto a
454	     * business day (a Saturday, Sunday or public holiday rolls forward to the next business day).
455	     * Returns the resolved date.
456	     * Idempotent, so it is safe to call from both the create flow and the persist hook.
457	     */
458	    public LocalDate resolveRegistrationDate() {
459	        LocalDate effective = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
460	        this.registrationDate = toBusinessDay(effective);
461	        return this.registrationDate;
462	    }
463	
464	    /**
465	     * Derives the fiscal year that a date falls in, where each fiscal year starts on 1 July and is
466	     * identified by the calendar year in which it ends: a date from July onwards belongs to the
467	     * fiscal year ending in the following calendar year (e.g. 2 July 2026 gives 2027), while a date
468	     * from January to June belongs to the fiscal year ending in its own calendar year. Returns
469	     * {@code null} when the date is absent.
470	     */
471	    public static Integer fiscalYear(LocalDate date) {
472	        if (date == null) {
473	            return null;
474	        }
475	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
476	    }
477	
478	    /**
479	     * Rolls a registration date forward onto a business day: a Saturday, Sunday or listed public
480	     * holiday is advanced to the next non-holiday weekday, while any other weekday (and {@code null})
481	     * is returned unchanged. Applying this to a date that is already a business day is a no-op, so it
482	     * is safe to call more than once.
483	     */
484	    public static LocalDate toBusinessDay(LocalDate date) {
485	        if (date == null) {
486	            return null;
487	        }
488	        LocalDate result = date;
489	        while (isWeekend(result) || PUBLIC_HOLIDAYS.contains(result)) {
490	            result = result.plusDays(1);
491	        }
492	        return result;
493	    }
494	
495	    private static boolean isWeekend(LocalDate date) {
496	        return switch (date.getDayOfWeek()) {
497	            case SATURDAY, SUNDAY -> true;
498	            default -> false;
499	        };
500	    }
501	
502	    protected Set<Pet> getPetsInternal() {
503	        if (this.pets == null) {
504	            this.pets = new HashSet<>();
505	        }
506	        return this.pets;
507	    }
508	
509	    protected void setPetsInternal(Set<Pet> pets) {
510	        this.pets = pets;
511	    }
512	
513	    public List<Pet> getPets() {
514	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
515	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
516	        return Collections.unmodifiableList(sortedPets);
517	    }
518	
519	    public void setPets(List<Pet> pets) {
520	        this.pets = new HashSet<>(pets);
521	    }
522	
523	    public void addPet(Pet pet) {
524	        getPetsInternal().add(pet);
525	        pet.setOwner(this);
526	    }
527	
528	    /**
529	     * Return the Pet with the given name, or null if none found for this Owner.
530	     *
531	     * @param name to test
532	     * @return true if pet name is already in use
533	     */
534	    public Pet getPet(String name) {
535	        return getPet(name, false);
536	    }
537	
538	    /**
539	     * Return the Pet with the given name, or null if none found for this Owner.
540	     *
541	     * @param name to test
542	     * @return true if pet name is already in use
543	     */
544	    public Pet getPet(String name, boolean ignoreNew) {
545	        name = name.toLowerCase();
546	        for (Pet pet : getPetsInternal()) {
547	            if (!ignoreNew || !pet.isNew()) {
548	                String compName = pet.getName();
549	                compName = compName.toLowerCase();
550	                if (compName.equals(name)) {
551	                    return pet;
552	                }
553	            }
554	        }
555	        return null;
556	    }
557	
558	    public Pet getPet(Integer petId) {
559	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
560	    }
561	
562	    @Override
563	    public String toString() {
564	        return new ToStringCreator(this)
565	
566	            .append("id", this.getId())
567	            .append("new", this.isNew())
568	            .append("lastName", this.getLastName())
569	            .append("firstName", this.getFirstName())
570	            .append("address", this.address)
571	            .append("city", this.city)
572	            .append("telephone", this.telephone)
573	            .toString();
574	    }
575	}
